16	// Some utilities for parsing Markdown content. These things are only used on
17	// server-side when we infer metadata like `title` and `description` from the
18	// content. Most parsing is still done in MDX through the mdx-loader.
19	
20	/**
21	 * Parses custom ID from a heading. The ID can contain any characters except
22	 * `{#` and `}`.
23	 *
24	 * @param heading e.g. `## Some heading {#some-heading}` where the last
25	 * character must be `}` for the ID to be recognized
26	 */
27	export function parseMarkdownHeadingId(heading: string): {
28	  /**
29	   * The heading content sans the ID part, right-trimmed. e.g. `## Some heading`
30	   */
31	  text: string;
32	  /** The heading ID. e.g. `some-heading` */
33	  id: string | undefined;
34	} {
35	  const customHeadingIdRegex = /\s*\{#(?<id>(?:.(?!\{#|\}))*.)\}$/;
36	  const matches = customHeadingIdRegex.exec(heading);
37	  if (matches) {
38	    return {
39	      text: heading.replace(matches[0]!, ''),
40	      id: matches.groups!.id!,
41	    };
42	  }
43	  return {text: heading, id: undefined};
44	}
45	
46	/**
47	 * MDX 2 requires escaping { with a \ so our anchor syntax need that now.
48	 * See https://mdxjs.com/docs/troubleshooting-mdx/#could-not-parse-expression-with-acorn-error
49	 */
50	export function escapeMarkdownHeadingIds(content: string): string {
51	  const markdownHeadingRegexp = /(?:^|\n)#{1,6}(?!#).*/g;
52	  return content.replaceAll(markdownHeadingRegexp, (substring) =>
53	    // TODO probably not the most efficient impl...
54	    substring
55	      .replace('{#', '\\{#')
56	      // prevent duplicate escaping
57	      .replace('\\\\{#', '\\{#'),
58	  );
59	}
60	
61	/**
62	 * Hacky temporary escape hatch for Crowdin bad MDX support
63	 * See https://docusaurus.io/docs/i18n/crowdin#mdx
64	 *
65	 * TODO Titus suggested a clean solution based on ```mdx eval and Remark
66	 * See https://github.com/mdx-js/mdx/issues/701#issuecomment-947030041
67	 *
68	 * @param content
69	 */
70	export function unwrapMdxCodeBlocks(content: string): string {
71	  // We only support 3/4 backticks on purpose, should be good enough
72	  const regexp3 =
73	    /(?<begin>^|\r?\n)(?<indentStart>\x20*)```(?<spaces>\x20*)mdx-code-block\r?\n(?<children>.*?)\r?\n(?<indentEnd>\x20*)```(?<end>\r?\n|$)/gs;
74	  const regexp4 =
75	    /(?<begin>^|\r?\n)(?<indentStart>\x20*)````(?<spaces>\x20*)mdx-code-block\r?\n(?<children>.*?)\r?\n(?<indentEnd>\x20*)````(?<end>\r?\n|$)/gs;
76	
77	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
78	  const replacer = (substring: string, ...args: any[]) => {
79	    const groups = args.at(-1);
80	    return `${groups.begin}${groups.children}${groups.end}`;
81	  };
82	
83	  return content.replaceAll(regexp3, replacer).replaceAll(regexp4, replacer);
84	}
85	
86	/**
87	 * Add support for our legacy ":::note Title" admonition syntax
88	 * Not supported by https://github.com/remarkjs/remark-directive
89	 * Syntax is transformed to ":::note[Title]" (container directive label)
90	 * See https://talk.commonmark.org/t/generic-directives-plugins-syntax/444
91	 *
92	 * @param content
93	 * @param admonitionContainerDirectives
94	 */
95	export function admonitionTitleToDirectiveLabel(
96	  content: string,
97	  admonitionContainerDirectives: string[],
98	): string {
99	  // this will also process ":::note Title" inside docs code blocks
100	  // good enough: we fixed older versions docs to not be affected
101	
102	  const directiveNameGroup = `(${admonitionContainerDirectives.join('|')})`;
103	  const regexp = new RegExp(
104	    `^(?<quote>(> ?)*)(?<indentation>( +|\t+))?(?<directive>:{3,}${directiveNameGroup}) +(?<title>.*)$`,
105	    'gm',
106	  );
107	
108	  return content.replaceAll(regexp, (substring, ...args: any[]) => {
109	    const groups = args.at(-1);
110	
111	    return `${groups.quote ?? ''}${groups.indentation ?? ''}${
112	      groups.directive
113	    }[${groups.title}]`;
114	  });
115	}
