8	import fs from 'fs-extra';
9	import logger from '@docusaurus/logger';
10	import {
11	  safeGlobby,
12	  writeMarkdownHeadingId,
13	  type WriteHeadingIDOptions,
14	} from '@docusaurus/utils';
15	import {loadContext} from '../server/site';
16	import {initPlugins} from '../server/plugins/init';
17	
18	async function transformMarkdownFile(
19	  filepath: string,
20	  options?: WriteHeadingIDOptions,
21	): Promise<string | undefined> {
22	  const content = await fs.readFile(filepath, 'utf8');
23	  const updatedContent = writeMarkdownHeadingId(content, options);
24	  if (content !== updatedContent) {
25	    await fs.writeFile(filepath, updatedContent);
26	    return filepath;
27	  }
28	  return undefined;
29	}
30	
31	/**
32	 * We only handle the "paths to watch" because these are the paths where the
33	 * markdown files are. Also we don't want to transform the site md docs that do
34	 * not belong to a content plugin. For example ./README.md should not be
35	 * transformed
36	 */
37	async function getPathsToWatch(siteDir: string): Promise<string[]> {
38	  const context = await loadContext({siteDir});
39	  const plugins = await initPlugins(context);
40	  return plugins.flatMap((plugin) => plugin.getPathsToWatch?.() ?? []);
41	}
42	
43	export async function writeHeadingIds(
44	  siteDirParam: string = '.',
45	  files: string[] = [],
46	  options: WriteHeadingIDOptions = {},
47	): Promise<void> {
48	  const siteDir = await fs.realpath(siteDirParam);
49	
50	  const patterns = files.length ? files : await getPathsToWatch(siteDir);
51	
52	  const markdownFiles = await safeGlobby(patterns, {
53	    expandDirectories: ['**/*.{md,mdx}'],
54	  });
55	
56	  if (markdownFiles.length === 0) {
57	    logger.warn`No markdown files found in siteDir path=${siteDir} for patterns: ${patterns}`;
58	    return;
59	  }
60	
61	  const result = await Promise.all(
62	    markdownFiles.map((p) => transformMarkdownFile(p, options)),
63	  );
64	
65	  const pathsModified = result.filter(Boolean) as string[];
66	
67	  if (pathsModified.length) {
68	    logger.success`Heading ids added to Markdown files (number=${`${pathsModified.length}/${markdownFiles.length}`} files): ${pathsModified}`;
69	  } else {
70	    logger.warn`number=${
71	      markdownFiles.length
72	    } Markdown files already have explicit heading IDs. If you intend to overwrite the existing heading IDs, use the code=${'--overwrite'} option.`;
73	  }
74	}
