import {createSlugger, type Slugger, type SluggerOptions} from './slugger';

/**
 * The supported syntaxes for custom heading IDs.
 *
 * - `'classic'` uses the `{#id}` format.
 * - `'mdx-comment'` uses the `{/* #id *␣/}` format (an MDX comment).
 */
export type HeadingIdSyntax = 'classic' | 'mdx-comment';

const HeadingIdRegex: {[syntax in HeadingIdSyntax]: RegExp} = {
  // The ID can contain any characters except `{#` and `}`.
  classic: /\s*\{#(?<id>(?:.(?!\{#|\}))*.)\}$/,
  // The ID is a single "word" (no internal whitespace) prefixed by `#`,
  // wrapped in an MDX comment. Whitespace around the ID is trimmed.
  'mdx-comment': /\s*\{\/\*\s*#(?<id>\S+?)\s*\*\/\}$/,
};

/**
 * Parses custom ID from a heading. The recognized syntax depends on the
 * `syntax` parameter. In all cases, the ID is only recognized when it appears
 * at the very end of the heading.
 *
 * @param heading e.g. `## Some heading {#some-heading}` where the last
 * character must be `}` for the ID to be recognized
 * @param syntax the heading ID syntax to recognize (defaults to `'classic'`)
 */
export function parseMarkdownHeadingId(
  heading: string,
  syntax: HeadingIdSyntax = 'classic',
): {
  /**
   * The heading content sans the ID part, right-trimmed. e.g. `## Some heading`
   */
  text: string;
  /** The heading ID. e.g. `some-heading` */
  id: string | undefined;
} {
  const customHeadingIdRegex = HeadingIdRegex[syntax];
  const matches = customHeadingIdRegex.exec(heading);
  if (matches) {
    return {
      text: heading.replace(matches[0]!, ''),
      id: matches.groups!.id!,
    };
  }
  return {text: heading, id: undefined};
}

// Parses a heading ID written in any of the supported syntaxes.
function parseMarkdownHeadingIdAnySyntax(heading: string): {
  text: string;
  id: string | undefined;
} {
  const classic = parseMarkdownHeadingId(heading, 'classic');
  if (classic.id) {
    return classic;
  }
  return parseMarkdownHeadingId(heading, 'mdx-comment');
}

// Formats a heading ID for a given syntax.
function formatHeadingId(id: string, syntax: HeadingIdSyntax): string {
  switch (syntax) {
    case 'mdx-comment':
      return `{/* #${id} */}`;
    case 'classic':
    default:
      return `{#${id}}`;
  }
}

/**
 * MDX 2 requires escaping { with a \ so our anchor syntax need that now.
 * See https://mdxjs.com/docs/troubleshooting-mdx/#could-not-parse-expression-with-acorn-error
 */
export function escapeMarkdownHeadingIds(content: string): string {
  const markdownHeadingRegexp = /(?:^|\n)#{1,6}(?!#).*/g;
  return content.replaceAll(markdownHeadingRegexp, (substring) =>
    // TODO probably not the most efficient impl...
    substring
      .replace('{#', '\\{#')
      // prevent duplicate escaping
      .replace('\\\\{#', '\\{#'),
  );
}

function unwrapMarkdownLinks(line: string): string {
  return line.replace(
    /\[(?<alt>[^\]]+)\]\([^)]+\)/g,
    (match, p1: string) => p1,
  );
}

function addHeadingId(
  line: string,
  slugger: Slugger,
  maintainCase: boolean,
  syntax: HeadingIdSyntax,
): string {
  let headingLevel = 0;
  while (line.charAt(headingLevel) === '#') {
    headingLevel += 1;
  }

  const headingText = line.slice(headingLevel).trimEnd();
  const headingHashes = line.slice(0, headingLevel);
  const slug = slugger.slug(unwrapMarkdownLinks(headingText).trim(), {
    maintainCase,
  });

  return `${headingHashes}${headingText} ${formatHeadingId(slug, syntax)}`;
}

export type WriteHeadingIDOptions = SluggerOptions & {
  /** The syntax to use when writing heading IDs. */
  syntax?: HeadingIdSyntax;
  /**
   * Rewrite existing heading IDs (in any syntax) using the target syntax, while
   * preserving their existing ID values.
   */
  migrate?: boolean;
  /** Overwrite existing heading IDs. */
  overwrite?: boolean;
};

/**
 * Takes Markdown content, returns new content with heading IDs written.
 * Respects existing IDs (unless `overwrite=true`) and never generates colliding
 * IDs (through the slugger).
 */
export function writeMarkdownHeadingId(
  content: string,
  options?: WriteHeadingIDOptions,
): string {
  const {
    maintainCase = false,
    overwrite = false,
    migrate = false,
    syntax = 'classic',
  } = options ?? {};

  if (overwrite && migrate) {
    throw new Error(
      'Heading ids can either be overwritten or migrated, not both at the same time',
    );
  }

  const lines = content.split('\n');
  const slugger = createSlugger();

  // If we can't overwrite existing slugs, make sure other headings don't
  // generate colliding slugs by first marking these slugs as occupied
  if (!overwrite) {
    lines.forEach((line) => {
      const parsedHeading = parseMarkdownHeadingIdAnySyntax(line);
      if (parsedHeading.id) {
        slugger.slug(parsedHeading.id);
      }
    });
  }

  let inCode = false;
  return lines
    .map((line) => {
      if (line.startsWith('```')) {
        inCode = !inCode;
        return line;
      }
      // Ignore h1 headings, as we don't create anchor links for those
      if (inCode || !line.startsWith('##')) {
        return line;
      }
      const parsedHeading = parseMarkdownHeadingIdAnySyntax(line);

      if (parsedHeading.id) {
        // Discard the existing id and generate a new one from the text
        if (overwrite) {
          return addHeadingId(
            parsedHeading.text,
            slugger,
            maintainCase,
            syntax,
          );
        }
        // Preserve the existing id, but rewrite it using the target syntax
        if (migrate) {
          return `${parsedHeading.text} ${formatHeadingId(
            parsedHeading.id,
            syntax,
          )}`;
        }
        // Keep the heading as-is
        return line;
      }
      return addHeadingId(parsedHeading.text, slugger, maintainCase, syntax);
    })
    .join('\n');
}
